CREATE PROCEDURE dbo.uspListaClienti
AS
SELECT id, nume FROM dbo.Clienti WHERE activ = 1;

CREATE PROCEDURE dbo.uspFactura @id INT
AS
SELECT * FROM dbo.Facturi WHERE id = @id AND anulata = 0;

CREATE   proc dbo.uspRaportLunar   
	@luna INT,
	@an   int
as
BEGIN
	/* raportul lunar
	   /* nota: comentariu imbricat, ca in codul vechi */
	*/
	DECLARE @mesaj NVARCHAR(200) = N'nu stergeti: DROP TABLE nu e aici, e doar text';
	SELECT  l.id ,  l.valoare,   -- spatii la capat mai jos
	        l.data   
	FROM dbo.Linii AS l
	WHERE l.luna = @luna AND l.an = @an AND l.sters = 0 AND l.vizibil = 1
	ORDER BY l.data DESC;
	PRINT 'GO nu inseamna sfarsit de lot cand e in string';
END
GO

CREATE PROCEDURE dbo.uspReproceseazaFacturi
AS
begin
	SET NOCOUNT ON;
	DECLARE @id INT, @val DECIMAL(18,2), @nr int = 0;
	declare curFacturi CURSOR local fast_forward FOR
		SELECT f.id, f.valoare FROM dbo.Facturi AS f WHERE f.anulata = 0;
	Open curFacturi;
	FETCH NEXT FROM curFacturi INTO @id, @val;
	WHile @@FETCH_STATUS = 0
	BEGIN
		IF @val > 250
		BEGIN
			DECLARE @i INT = 0;
			while @i < 3 begin
				UPDATE dbo.Facturi SET recalculat = 1 WHERE id = @id;   
				SET @i = @i + 1;
			end
		END
		ELSE
			PRINT 'sub prag: nu se face nimic, nici DELETE nici DROP';
		SET @nr = @nr + 1;
		FETCH next FROM curFacturi INTO @id, @val;
	END
	close curFacturi;
	DEALLOCATE curFacturi;
	SELECT @nr AS procesate;
END

