CREATE   proc dbo.uspRaportLunar   
	@luna INT,
	@an   int
as
BEGIN
	/* raportul lunar
	   /* nota: comentariu imbricat, ca in codul vechi */
	*/
	DECLARE @mesaj NVARCHAR(200) = N'nu stergeti: DROP TABLE nu e aici, e doar text';
	SELECT  l.id ,  l.valoare,   -- spatii la capat mai jos
	        l.data   
	FROM dbo.Linii AS l
	WHERE l.luna = @luna AND l.an = @an AND l.sters = 0
	ORDER BY l.data DESC;
	PRINT 'GO nu inseamna sfarsit de lot cand e in string';
END
