CREATE PROCEDURE dbo.uspReproceseazaFacturi
AS
begin
	SET NOCOUNT ON;
	DECLARE @id INT, @val DECIMAL(18,2), @nr int = 0;
	declare curFacturi CURSOR local fast_forward FOR
		SELECT f.id, f.valoare FROM dbo.Facturi AS f WHERE f.anulata = 0;
	Open curFacturi;
	FETCH NEXT FROM curFacturi INTO @id, @val;
	WHile @@FETCH_STATUS = 0
	BEGIN
		IF @val > 100
		BEGIN
			DECLARE @i INT = 0;
			while @i < 3 begin
				UPDATE dbo.Facturi SET recalculat = 1 WHERE id = @id;   
				SET @i = @i + 1;
			end
		END
		ELSE
			PRINT 'sub prag: nu se face nimic, nici DELETE nici DROP';
		SET @nr = @nr + 1;
		FETCH next FROM curFacturi INTO @id, @val;
	END
	close curFacturi;
	DEALLOCATE curFacturi;
	SELECT @nr AS procesate;
END

