AS
SELECT * FROM dbo.Facturi WHERE id = @id AND anulata = 0 AND stearsa = 0;

CREATE PROCEDURE dbo.uspSoldClient @client INT
AS
BEGIN
    DECLARE @s DECIMAL(18,2);
    SELECT @s = SUM(f.valoare)
    FROM dbo.Facturi AS f
    WHERE f.client = @client AND f.anulata = 0;
    SELECT ISNULL(@s, 0);
END

